&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;bhla9&quot; data-offset-key=&quot;1v0gg-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;1v0gg-0-0&quot;&gt;&lt;span class=&quot;style_handle__4nndx style_hasReplacements__2Gq83 style_masculine__1PshY&quot;&gt;&lt;span data-offset-key=&quot;1v0gg-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Lead&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;1v0gg-1-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; the coordination and technical assurance of multi-disciplinary design outputs, ensuring compliance with industry standards, regulatory frameworks, and client specifications (e.g. DNO/TSO, Ofgem, environmental and planning constraints)&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
