&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;bhla9&quot; data-offset-key=&quot;5poqb-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;5poqb-0-0&quot;&gt;&lt;span data-offset-key=&quot;5poqb-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Manage design delivery against contracted scope, ensuring alignment with project objectives, programme and budget&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;bhla9&quot; data-offset-key=&quot;6mrg1-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;6mrg1-0-0&quot;&gt;&lt;span data-offset-key=&quot;6mrg1-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Develop and maintain integrated design programmes that reflect complex asset interfaces, project sequencing, outages and commissioning constraints&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
